def compute(vars):
    numerator_2012 = vars["v1"]
    denominator_2011 = vars["v2"]

    if denominator_2011 == 0:
        return {"value": None, "trace": {
            "numerator_2012": numerator_2012,
            "denominator_2011": denominator_2011,
            "output_meta": {"currency": None, "scale": "ones", "unit": "ratio"}
        }}

    ratio = numerator_2012 / denominator_2011
    return {
        "value": ratio,
        "trace": {
            "numerator_2012": numerator_2012,
            "denominator_2011": denominator_2011,
            "output_meta": {"currency": None, "scale": "ones", "unit": "ratio"}
        }
    }
